// This avoids crashes and is not vulnerable to overflow
public int addNumbersSafe(String a, String b) {
    int num1 = Integer.parseInt(a);
    int num2 = Integer.parseInt(b);
    if (num1 < 0 && num2 < 0) { // Handle negative numbers correctly
        return num1 + num2;
    } else if (num1 >= 0 && num2 >= 0) {
